    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AO = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">EO = 10</span>  و  <span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(BD) // (CE)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">OB.</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AO = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 6</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BO = 9</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BO = 3 + 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BO = 9</span>"},{"quoi":"2)","math":"أحسب النّسبة <span dir=\"ltr\" class=\"expr pt\">OD/OE.</span>"},{"quoi":"القاعدة","math":"بتطبيق نظرية طالس على كلّ متوازيين، نحصل على العلاقة بين النّسب"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">AO = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">BO = 9</span>  إذن  <span class=\"frac\" dir=\"ltr\"><span class=\"num\">OD</span><span class=\"den\">OE</span></span> <span dir=\"ltr\" class=\"expr\">=</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">1</span><span class=\"den\">3</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">OD</span><span class=\"den\">OE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">1</span><span class=\"den\">3</span></span>"},{"quoi":"3)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">OD.</span>"},{"quoi":"في المثلّث OBE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">A ∈ (OB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (OE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AO</span><span class=\"den\">BO</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">DO</span><span class=\"den\">EO</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AD</span><span class=\"den\">BE</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">9</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">DO</span><span class=\"den\">10</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">DO = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">10</span><span class=\"den\">3</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">DO = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">10</span><span class=\"den\">3</span></span>"},{"quoi":"4)","math":"بيّن أنّ <span dir=\"ltr\" class=\"expr pt\">OB/OC = OD/OE.</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(BD) // (CE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">DO =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">10</span><span class=\"den\">3</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">EO = 10</span>  إذن  <span class=\"frac\" dir=\"ltr\"><span class=\"num\">OB</span><span class=\"den\">OC</span></span> <span dir=\"ltr\" class=\"expr\">=</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">1</span><span class=\"den\">3</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">OB</span><span class=\"den\">OC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">1</span><span class=\"den\">3</span></span>"}],
